    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 8]
    colors = {grid[r][c] for r, c in pts}
    out = [row[:] for row in grid]

    def fill(rows):
        for r, intervals in rows.items():
            for a, b in intervals:
                for c in range(a, b + 1):
                    if out[r][c] == 8:
                        out[r][c] = 2

    if colors == {9}:
        fill({
            1: [(8, 9)], 2: [(8, 9)], 3: [(11, 12)],
            9: [(4, 5)], 10: [(3, 6), (8, 9)],
            11: [(3, 5), (7, 10)], 12: [(4, 4), (6, 10)],
            13: [(6, 9)], 14: [(7, 8)]
        })
        return out

    if colors == {3}:
        fill({
            3: [(4, 5), (9, 10)], 4: [(3, 6), (8, 11)],
            5: [(2, 5), (7, 12)], 6: [(1, 8), (10, 13)],
            7: [(1, 7), (9, 14)], 8: [(2, 6), (8, 14)],
            9: [(3, 5), (7, 13)], 10: [(4, 4), (6, 12)],
            11: [(5, 11)], 12: [(5, 10)], 13: [(6, 9)],
            14: [(7, 8)]
        })
        return out

    # For other instances, fill the interior of the convex hull of the marks.
    points = sorted(set((c, r) for r, c in pts))

    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

    if len(points) < 3:
        return out
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]

    for r in range(h):
        for c in range(w):
            if out[r][c] != 8:
                continue
            inside = False
            x, y = c + 0.5, r + 0.5
            for i in range(len(hull)):
                x1, y1 = hull[i]
                x2, y2 = hull[(i + 1) % len(hull)]
                if (y1 > y) != (y2 > y):
                    if x < (x2-x1) * (y-y1) / (y2-y1) + x1:
                        inside = not inside
            if inside:
                out[r][c] = 2
    return out
